WITH "_src_normalized" AS (SELECT "src"."id" AS "id", "src"."region" AS "region", "src"."amount" AS "amount", "src"."qty" AS "qty", "src"."note" AS "note", "src"."active" AS "active", "src"."price" AS "price" FROM "shop"."orders_v1" AS "src"), "_tgt_normalized" AS (SELECT "tgt"."id" AS "id", "tgt"."region" AS "region", "tgt"."amount" AS "amount", "tgt"."qty" AS "qty", "tgt"."note" AS "note", "tgt"."active" AS "active", "tgt"."price" AS "price" FROM "shop"."orders_v2" AS "tgt") SELECT SUM(CASE WHEN COALESCE(("src"."amount" IS NULL AND "tgt"."amount" IS NULL) OR (("src"."amount" = "tgt"."amount" OR (ABS("src"."amount") < 'Infinity'::double precision AND ABS("tgt"."amount" - "src"."amount") <= 0.5 + (0.01 * ABS("src"."amount"))))), FALSE) THEN 0 ELSE 1 END) AS "amount", SUM(CASE WHEN COALESCE(("src"."qty" IS NULL AND "tgt"."qty" IS NULL) OR ((CAST("src"."qty" AS NUMERIC(38, 0)) = CAST("tgt"."qty" AS NUMERIC(38, 0)) OR ABS(CAST("tgt"."qty" AS NUMERIC(38, 0)) - CAST("src"."qty" AS NUMERIC(38, 0))) <= 1.0 + (0.0 * ABS(CAST("src"."qty" AS NUMERIC(38, 0)))))), FALSE) THEN 0 ELSE 1 END) AS "qty", SUM(CASE WHEN COALESCE("src"."note" IS NOT DISTINCT FROM "tgt"."note", FALSE) THEN 0 ELSE 1 END) AS "note", SUM(CASE WHEN COALESCE("src"."active" IS NOT DISTINCT FROM "tgt"."active", FALSE) THEN 0 ELSE 1 END) AS "active", SUM(CASE WHEN COALESCE(("src"."price" IS NULL AND "tgt"."price" IS NULL) OR (("src"."price" = "tgt"."price" OR (ABS("src"."price") < 'Infinity'::double precision AND ABS("tgt"."price" - "src"."price") <= 0.01 + (0.0 * ABS("src"."price"))))), FALSE) THEN 0 ELSE 1 END) AS "price" FROM "_src_normalized" AS "src" INNER JOIN "_tgt_normalized" AS "tgt" ON "src"."id" = "tgt"."id" AND "src"."region" = "tgt"."region"

